      // loading (issue #135) on big session files. (fa writers never emit
      // blank lines, so "second line empty" can only mean "no content".)
      final lines = _fsOrThrow(
        await _fs.readTextLines(path, maxLines: 2),
        'Failed to read $path',
      );
