      // by the controller until the program's event loop is listening).
      await _runTuiRepl();
    } else {
      await _runLineRepl();
    }
  } finally {
    await _teardownAfterRepl(interruptSub, taskSub, inboxTimer);
  }
  await printSessionResumeHint();
}

